import type { RequestHandler } from '@builder.io/qwik-city';
import db from '../../../../../utils/db';
import { generateApiKey, hashApiKey, getPrefix } from '../../../../../utils/keys';

export const onPost: RequestHandler = async (event) => {
  try {
    const body = await event.parseBody() as any;
    if (!body || typeof body.name !== 'string' || !body.name.trim()) {
      event.json(400, { error: 'Name is required' });
      return;
    }

    const name = body.name.trim();
    const plainKey = generateApiKey();
    const prefix = getPrefix(plainKey);
    const hashed = hashApiKey(plainKey);
    const status = 'active';
    const createdAt = new Date().toISOString();

    const stmt = db.prepare(`
      INSERT INTO api_keys (name, key_prefix, hashed_key, status, created_at)
      VALUES (?, ?, ?, ?, ?)
    `);
    const info = stmt.run(name, prefix, hashed, status, createdAt);
    const id = Number(info.lastInsertRowid);

    event.json(201, {
      id,
      name,
      prefix,
      key: plainKey,
      status,
      created_at: createdAt
    });
  } catch (err: any) {
    event.json(500, { error: err.message });
  }
};

export const onGet: RequestHandler = async (event) => {
  try {
    const stmt = db.prepare(`
      SELECT id, name, key_prefix AS prefix, status, created_at
      FROM api_keys
      ORDER BY id DESC
    `);
    const rows = stmt.all();
    event.json(200, rows);
  } catch (err: any) {
    event.json(500, { error: err.message });
  }
};

import type { RequestHandler } from '@builder.io/qwik-city';
import db from '../../../../../../../utils/db';

export const onPost: RequestHandler = async (event) => {
  try {
    const idStr = event.params.id;
    const id = parseInt(idStr, 10);

    if (isNaN(id)) {
      event.json(400, { error: 'Invalid key ID' });
      return;
    }

    // Check if key exists
    const checkStmt = db.prepare('SELECT id FROM api_keys WHERE id = ?');
    const keyExists = checkStmt.get(id);

    if (!keyExists) {
      event.json(404, { error: 'Key not found' });
      return;
    }

    // Update status to revoked
    const updateStmt = db.prepare("UPDATE api_keys SET status = 'revoked' WHERE id = ?");
    updateStmt.run(id);

    event.json(200, {
      success: true,
      message: 'Key revoked successfully'
    });
  } catch (err: any) {
    event.json(500, { error: err.message });
  }
};

import type { RequestHandler } from '@builder.io/qwik-city';
import db from '../../../../utils/db';
import { hashApiKey } from '../../../../utils/keys';

export const onGet: RequestHandler = async (event) => {
  try {
    const apiKey = event.request.headers.get('X-API-Key');

    if (!apiKey || !apiKey.startsWith('qk_')) {
      event.json(401, { error: 'Unauthorized' });
      return;
    }

    const hashed = hashApiKey(apiKey);
    const stmt = db.prepare("SELECT status FROM api_keys WHERE hashed_key = ?");
    const row = stmt.get(hashed) as { status: string } | undefined;

    if (!row || row.status !== 'active') {
      event.json(401, { error: 'Unauthorized' });
      return;
    }

    event.json(200, {
      message: 'Hello, authenticated developer!'
    });
  } catch (err: any) {
    event.json(500, { error: err.message });
  }
};

/* Reset & Base Styles */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: #f8fafc;
  color: #1e293b;
  line-height: 1.5;
}

.container {
  max-width: 1000px;
  margin: 0 auto;
  padding: 2rem 1.5rem;
}

header {
  margin-bottom: 2rem;
  border-bottom: 1px solid #e2e8f0;
  padding-bottom: 1rem;
}

header h1 {
  font-size: 2rem;
  font-weight: 700;
  color: #0f172a;
}

header p {
  color: #64748b;
  margin-top: 0.25rem;
}

/* Cards */
.card {
  background-color: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 0.5rem;
  box-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px -1px rgba(0, 0, 0, 0.1);
  padding: 1.5rem;
  margin-bottom: 2rem;
}

.card h2 {
  font-size: 1.25rem;
  font-weight: 600;
  color: #0f172a;
  margin-bottom: 1rem;
}

/* Forms */
.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

.form-group label {
  font-size: 0.875rem;
  font-weight: 500;
  color: #475569;
}

.input-control {
  padding: 0.625rem 0.875rem;
  font-size: 0.875rem;
  border: 1px solid #cbd5e1;
  border-radius: 0.375rem;
  outline: none;
  transition: border-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out;
}

.input-control:focus {
  border-color: #6366f1;
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.2);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.625rem 1.25rem;
  font-size: 0.875rem;
  font-weight: 500;
  border-radius: 0.375rem;
  border: 1px solid transparent;
  cursor: pointer;
  transition: background-color 0.15s ease-in-out;
}

.btn-primary {
  background-color: #4f46e5;
  color: #ffffff;
}

.btn-primary:hover {
  background-color: #4338ca;
}

.btn-danger {
  background-color: #ef4444;
  color: #ffffff;
}

.btn-danger:hover {
  background-color: #dc2626;
}

.btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

/* Table */
.table-responsive {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.875rem;
}

th {
  background-color: #f1f5f9;
  color: #475569;
  font-weight: 600;
  padding: 0.75rem 1rem;
  border-bottom: 1px solid #e2e8f0;
}

td {
  padding: 1rem;
  border-bottom: 1px solid #e2e8f0;
  color: #334155;
}

tr:last-child td {
  border-bottom: none;
}

/* Badges */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 0.25rem 0.5rem;
  font-size: 0.75rem;
  font-weight: 500;
  border-radius: 9999px;
}

.badge-success {
  background-color: #d1fae5;
  color: #065f46;
}

.badge-danger {
  background-color: #fee2e2;
  color: #991b1b;
}

/* Alerts */
.alert {
  padding: 1rem;
  border-radius: 0.375rem;
  margin-bottom: 1.5rem;
  font-size: 0.875rem;
}

.alert-success {
  background-color: #ecfdf5;
  border: 1px solid #a7f3d0;
  color: #065f46;
}

.alert-danger {
  background-color: #fef2f2;
  border: 1px solid #fca5a5;
  color: #991b1b;
}

.alert h3 {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.api-key-display {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-top: 0.75rem;
  background-color: #ffffff;
  border: 1px solid #a7f3d0;
  padding: 0.75rem;
  border-radius: 0.25rem;
  font-family: monospace;
  font-size: 1rem;
  word-break: break-all;
  user-select: all;
}

.no-keys {
  text-align: center;
  padding: 2rem;
  color: #64748b;
}

import { component$, useSignal } from '@builder.io/qwik';
import { routeLoader$, routeAction$, Form } from '@builder.io/qwik-city';
import db from '../../../utils/db';
import { generateApiKey, hashApiKey, getPrefix } from '../../../utils/keys';

export const useKeysLoader = routeLoader$(async () => {
  const stmt = db.prepare(`
    SELECT id, name, key_prefix AS prefix, status, created_at
    FROM api_keys
    ORDER BY id DESC
  `);
  return stmt.all() as { id: number; name: string; prefix: string; status: 'active' | 'revoked'; created_at: string }[];
});

export const useGenerateKeyAction = routeAction$(async (data) => {
  const name = (data.name as string || '').trim();
  if (!name) {
    return {
      success: false,
      error: 'Name is required'
    };
  }

  try {
    const plainKey = generateApiKey();
    const prefix = getPrefix(plainKey);
    const hashed = hashApiKey(plainKey);
    const status = 'active';
    const createdAt = new Date().toISOString();

    const stmt = db.prepare(`
      INSERT INTO api_keys (name, key_prefix, hashed_key, status, created_at)
      VALUES (?, ?, ?, ?, ?)
    `);
    stmt.run(name, prefix, hashed, status, createdAt);

    return {
      success: true,
      plainKey,
      name
    };
  } catch (err: any) {
    return {
      success: false,
      error: err.message
    };
  }
});

export const useRevokeKeyAction = routeAction$(async (data) => {
  const id = parseInt(data.id as string, 10);
  if (isNaN(id)) {
    return {
      success: false,
      error: 'Invalid key ID'
    };
  }

  try {
    const updateStmt = db.prepare("UPDATE api_keys SET status = 'revoked' WHERE id = ?");
    updateStmt.run(id);
    return {
      success: true
    };
  } catch (err: any) {
    return {
      success: false,
      error: err.message
    };
  }
});

export default component$(() => {
  const keysSignal = useKeysLoader();
  const generateAction = useGenerateKeyAction();
  const revokeAction = useRevokeKeyAction();

  const dismissedKey = useSignal<string | null>(null);

  const showSuccessBox =
    generateAction.value?.success &&
    generateAction.value?.plainKey &&
    dismissedKey.value !== generateAction.value.plainKey;

  return (
    <div class="container">
      <header>
        <h1>API Key Manager</h1>
        <p>Generate, view, and revoke API keys for your applications.</p>
      </header>

      {/* Prominent Alert Box for newly generated key */}
      {showSuccessBox && (
        <div class="alert alert-success">
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
            <div>
              <h3>API Key Generated Successfully!</h3>
              <p>
                Please copy your API key now. For security reasons, <strong>we cannot show it to you again</strong>.
              </p>
              <div class="api-key-display">
                <code>{generateAction.value.plainKey}</code>
              </div>
            </div>
            <button
              onClick$={() => {
                dismissedKey.value = generateAction.value!.plainKey!;
              }}
              class="btn"
              style={{
                background: 'transparent',
                border: 'none',
                color: '#065f46',
                fontWeight: 'bold',
                cursor: 'pointer',
                padding: '0 0.5rem',
                fontSize: '1.25rem'
              }}
              title="Dismiss"
            >
              &times;
            </button>
          </div>
        </div>
      )}

      {/* Error alert if actions fail */}
      {generateAction.value?.success === false && (
        <div class="alert alert-danger">
          <h3>Error Generating Key</h3>
          <p>{generateAction.value.error}</p>
        </div>
      )}

      {revokeAction.value?.success === false && (
        <div class="alert alert-danger">
          <h3>Error Revoking Key</h3>
          <p>{revokeAction.value.error}</p>
        </div>
      )}

      <div class="card">
        <h2>Generate New API Key</h2>
        <Form action={generateAction}>
          <div class="form-group">
            <label for="key-name">Key Name / Description</label>
            <input
              type="text"
              id="key-name"
              name="name"
              placeholder="e.g. Production Server Key"
              class="input-control"
              required
            />
          </div>
          <button type="submit" class="btn btn-primary" disabled={generateAction.isRunning}>
            {generateAction.isRunning ? 'Generating...' : 'Generate Key'}
          </button>
        </Form>
      </div>

      <div class="card">
        <h2>Your API Keys</h2>
        {keysSignal.value.length === 0 ? (
          <div class="no-keys">
            <p>You don't have any API keys yet. Generate one above!</p>
          </div>
        ) : (
          <div class="table-responsive">
            <table>
              <thead>
                <tr>
                  <th>Name</th>
                  <th>Prefix</th>
                  <th>Status</th>
                  <th>Created At</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {keysSignal.value.map((key) => {
                  const isRevokingThisKey =
                    revokeAction.isRunning &&
                    revokeAction.formData?.get('id') === String(key.id);

                  return (
                    <tr key={key.id}>
                      <td style={{ fontWeight: '500' }}>{key.name}</td>
                      <td>
                        <code style={{ backgroundColor: '#f1f5f9', padding: '0.2rem 0.4rem', borderRadius: '0.25rem' }}>
                          {key.prefix}
                        </code>
                      </td>
                      <td>
                        <span
                          class={`badge ${
                            key.status === 'active' ? 'badge-success' : 'badge-danger'
                          }`}
                        >
                          {key.status}
                        </span>
                      </td>
                      <td>{new Date(key.created_at).toLocaleString()}</td>
                      <td>
                        {key.status === 'active' ? (
                          <Form action={revokeAction}>
                            <input type="hidden" name="id" value={key.id} />
                            <button
                              type="submit"
                              class="btn btn-danger"
                              style={{ padding: '0.375rem 0.75rem', fontSize: '0.75rem' }}
                              disabled={isRevokingThisKey}
                            >
                              {isRevokingThisKey ? 'Revoking...' : 'Revoke'}
                            </button>
                          </Form>
                        ) : (
                          <span style={{ color: '#94a3b8', fontSize: '0.875rem' }}>Revoked</span>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
});

